{
    "name": "app/mongophp-mongodb-from-documents",
    "description": "Data access layer generated by DB2CRUD (MongoDB PHP library 2)",
    "type": "project",
    "license": "proprietary",
    "require": {
        "php": ">=8.4",
        "ext-mbstring": "*",
        "ext-mongodb": "^2.1",
        "mongodb/mongodb": "^2.1"
    },
    "require-dev": {
        "phpunit/phpunit": "^12.4"
    },
    "autoload": {
        "psr-4": {
            "App\\": "src/"
        }
    },
    "autoload-dev": {
        "psr-4": {
            "Tests\\": "tests/"
        }
    },
    "scripts": {
        "test": "phpunit"
    },
    "config": {
        "sort-packages": true
    }
}

